FAQ_GENERIC = {}

def words(html):
    t=re.sub(r'<(script|style)[\s\S]*?</\1>',' ',html,flags=re.I)
    t=re.sub(r'<[^>]+>',' ',t)
    return len(re.findall(r'[\wآ-ی]+',t))

